-- 0048: General Science batch 8 — chapters 911, 912, 913, 914, 915
-- Each chapter: 4 govt_technical, 4 govt_basic, 1 shared svg (level_id null). 9 atoms per chapter.

with src as (
  select v.chapter_id, v.level_id, v.atom_key, v.atom_type, v.atom_order, v.title, v.body::jsonb as body
  from (values
  (911,'govt_technical','exc-concept','concept',1,'उत्सर्जन — SSC JE / RRB JE',$j${"note":"परीक्षा में वृक्क की इकाई (नेफ्रॉन) और मूत्र निर्माण के चरण अक्सर पूछे जाते हैं।","text":"उत्सर्जन शरीर से अपशिष्ट पदार्थ निकालने की क्रिया है। मनुष्य का मुख्य उत्सर्जी अंग वृक्क (kidney) है, जिसकी संरचनात्मक और क्रियात्मक इकाई नेफ्रॉन है। नेफ्रॉन में रक्त छनकर बोमैन कैप्सूल में आता है, फिर पुनरावशोषण होता है और अंत में मूत्र बनता है।"}$j$),
  (911,'govt_technical','exc-formula','formula',2,'मूत्र निर्माण के चरण',$j${"formula":"छनन (ग्लोमेरुलस) → पुनरावशोषण (नलिका) → स्रावण → मूत्र","explanation":"ग्लूकोज़ और अमीनो अम्ल का पुनरावशोषण लगभग पूरा होता है"}$j$),
  (911,'govt_technical','exc-example','example',3,'Numerical (JE style)',$j${"question":"मनुष्य के मूत्र में मुख्य नाइट्रोजनी अपशिष्ट कौन सा होता है?","solution":"मनुष्य मुख्य रूप से यूरिया का उत्सर्जन करता है, जो यकृत में अमोनिया से बनता है","answer":"यूरिया"}$j$),
  (911,'govt_technical','exc-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"वृक्क की संरचनात्मक और क्रियात्मक इकाई क्या है?","options":["नेफ्रॉन","अलिंद","एल्वियोलस","न्यूरॉन"],"answer":0,"explanation":"नेफ्रॉन वृक्क की मूलभूत इकाई है जहाँ मूत्र बनता है।"},{"q":"मनुष्य में नाइट्रोजनी अपशिष्ट का मुख्य रूप कौन सा है?","options":["यूरिया","अमोनिया","यूरिक अम्ल","क्रिएटिनिन"],"answer":0,"explanation":"मनुष्य मुख्यतः यूरिया के रूप में नाइट्रोजन उत्सर्जित करता है।"}]}$j$),
  (911,'govt_basic','exc-concept','concept',1,'उत्सर्जन',$j${"note":"परीक्षा में उत्सर्जी अंगों के नाम और उनके कार्य पूछे जाते हैं।","text":"शरीर के अपशिष्ट पदार्थ मूत्र, पसीने, श्वास और मल के द्वारा बाहर निकलते हैं। वृक्क रक्त को साफ करके मूत्र बनाते हैं।"}$j$),
  (911,'govt_basic','exc-formula','formula',2,'उत्सर्जी अंग',$j${"formula":"वृक्क → मूत्र · त्वचा → पसीना · फेफड़े → CO₂","explanation":"ये सभी अपशिष्ट बाहर निकालने के मार्ग हैं"}$j$),
  (911,'govt_basic','exc-example','example',3,'उदाहरण',$j${"question":"वृक्क में बनने वाला द्रव क्या कहलाता है?","solution":"वृक्क में रक्त से छनकर जो द्रव बनता है और अंत में बाहर निकलता है, वह मूत्र है","answer":"मूत्र"}$j$),
  (911,'govt_basic','exc-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"मूत्र किस अंग में बनता है?","options":["वृक्क","यकृत","आमाशय","प्लीहा"],"answer":0,"explanation":"मूत्र का निर्माण वृक्क में होता है।"},{"q":"पसीने के द्वारा कौन सा पदार्थ बाहर निकलता है?","options":["जल और लवण","ऑक्सीजन","ग्लूकोज़","प्रोटीन"],"answer":0,"explanation":"पसीने के द्वारा जल, लवण और कुछ यूरिया निकलते हैं।"}]}$j$),
  (911,null,'exc-diagram','svg',5,'वृक्क और मूत्र मार्ग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><ellipse cx='70' cy='60' rx='30' ry='40' fill='#fca5a5'/><text x='70' y='115' text-anchor='middle' font-size='11' fill='#64748b'>वृक्क</text><line x1='100' y1='60' x2='160' y2='60' stroke='#64748b' stroke-width='4'/><rect x='160' y='45' width='60' height='30' fill='#fde047' rx='4'/><text x='190' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>मूत्राशय</text></svg>","caption":"वृक्क में मूत्र बनकर मूत्राशय में संग्रहित होता है"}$j$),
  (912,'govt_technical','nerv-concept','concept',1,'तंत्रिका तंत्र — SSC JE / RRB JE',$j${"note":"परीक्षा में न्यूरॉन के भाग, सिनैप्स और मस्तिष्क के भागों के कार्य अक्सर पूछे जाते हैं।","text":"तंत्रिका तंत्र शरीर का नियंत्रण और समन्वय करता है। इसकी मूल इकाई न्यूरॉन है। आवेग डेंड्राइट से कोशिका काय में आता है और एक्सॉन से आगे जाता है। दो न्यूरॉन के जुड़ाव को सिनैप्स कहते हैं, जहाँ रासायनिक संदेशवाहक (न्यूरोट्रांसमीटर) आवेग पहुँचाते हैं। मस्तिष्क का सेरेब्रम इच्छा और चिंतन, सेरेबेलम संतुलन और मेड्यूला श्वसन व हृदय गति नियंत्रित करता है।"}$j$),
  (912,'govt_technical','nerv-formula','formula',2,'मस्तिष्क के भाग और कार्य',$j${"formula":"सेरेब्रम → इच्छा और चिंतन · सेरेबेलम → संतुलन · मेड्यूला → श्वसन व हृदय","explanation":"हाइपोथैलेमस शरीर का तापमान और भूख नियंत्रित करता है"}$j$),
  (912,'govt_technical','nerv-example','example',3,'Numerical (JE style)',$j${"question":"शरीर का संतुलन और गति का समन्वय किस भाग से नियंत्रित होता है?","solution":"संतुलन और मांसपेशियों की गति का समन्वय सेरेबेलम करता है","answer":"सेरेबेलम"}$j$),
  (912,'govt_technical','nerv-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"तंत्रिका तंत्र की मूल इकाई क्या है?","options":["न्यूरॉन","नेफ्रॉन","एल्वियोलस","ऊतक"],"answer":0,"explanation":"न्यूरॉन तंत्रिका तंत्र की संरचनात्मक और क्रियात्मक इकाई है।"},{"q":"दो न्यूरॉन के जुड़ने के स्थान को क्या कहते हैं?","options":["सिनैप्स","एक्सॉन","डेंड्राइट","रसांकुर"],"answer":0,"explanation":"सिनैप्स वह बिंदु है जहाँ संदेश एक न्यूरॉन से दूसरे तक जाता है।"}]}$j$),
  (912,'govt_basic','nerv-concept','concept',1,'तंत्रिका तंत्र',$j${"note":"परीक्षा में मस्तिष्क के भाग और उनके कार्य पूछे जाते हैं।","text":"मस्तिष्क शरीर का मुख्य नियंत्रण केंद्र है। यह सोचने, याद रखने और अंगों को आदेश देने का काम करता है। मेरुरज्जु मस्तिष्क से शरीर तक संदेश पहुँचाती है।"}$j$),
  (912,'govt_basic','nerv-formula','formula',2,'ज्ञानेंद्रियाँ',$j${"formula":"आँख → देखना · कान → सुनना · नाक → सूंघना · जीभ → स्वाद · त्वचा → स्पर्श","explanation":"ये पाँच ज्ञानेंद्रियाँ बाहरी संकेत ग्रहण करती हैं"}$j$),
  (912,'govt_basic','nerv-example','example',3,'उदाहरण',$j${"question":"आँख का वह भाग कौन सा है जो प्रकाश को ग्रहण करके प्रतिबिंब बनाता है?","solution":"रेटिना प्रकाश संवेदी परत है, जहाँ प्रतिबिंब बनता है","answer":"रेटिना"}$j$),
  (912,'govt_basic','nerv-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"मनुष्य का सबसे बड़ा भाग मस्तिष्क का कौन सा है?","options":["सेरेब्रम","सेरेबेलम","मेड्यूला","हाइपोथैलेमस"],"answer":0,"explanation":"सेरेब्रम मस्तिष्क का सबसे बड़ा भाग है और इच्छा व चिंतन का केंद्र है।"},{"q":"सुनने की ज्ञानेंद्रिय कौन सी है?","options":["कान","आँख","नाक","जीभ"],"answer":0,"explanation":"कान ध्वनि तरंगों को ग्रहण करके सुनने का कार्य करते हैं।"}]}$j$),
  (912,null,'nerv-diagram','svg',5,'मानव मस्तिष्क के भाग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><ellipse cx='110' cy='55' rx='75' ry='42' fill='#fbcfe8' stroke='#db2777' stroke-width='2'/><text x='110' y='50' text-anchor='middle' font-size='11' fill='#0f172a'>सेरेब्रम</text><ellipse cx='200' cy='85' rx='35' ry='18' fill='#c4b5fd'/><text x='200' y='89' text-anchor='middle' font-size='10' fill='#0f172a'>सेरेबेलम</text><rect x='160' y='10' width='0' height='0'/></svg>","caption":"मस्तिष्क के मुख्य भाग: सेरेब्रम और सेरेबेलम"}$j$),
  (913,'govt_technical','horm-concept','concept',1,'हार्मोन — SSC JE / RRB JE',$j${"note":"परीक्षा में ग्रंथि, हार्मोन और उसकी कमी से होने वाले रोग अक्सर पूछे जाते हैं।","text":"हार्मोन अंतःस्रावी ग्रंथियों द्वारा सीधे रक्त में स्रावित रासायनिक संदेशवाहक हैं। इंसुलिन अग्न्याशय से निकलता है और रक्त शर्करा घटाता है। थायरॉक्सिन थायरॉइड से निकलता है और चयापचय नियंत्रित करता है। एड्रेनालिन अधिवृक्क से निकलता है और आपात स्थिति में हृदय गति बढ़ाता है।"}$j$),
  (913,'govt_technical','horm-formula','formula',2,'ग्रंथि और हार्मोन',$j${"formula":"अग्न्याशय → इंसुलिन · थायरॉइड → थायरॉक्सिन · अधिवृक्क → एड्रेनालिन","explanation":"इंसुलिन की कमी से मधुमेह (डायबिटीज़) होता है"}$j$),
  (913,'govt_technical','horm-example','example',3,'Numerical (JE style)',$j${"question":"इंसुलिन की कमी से किस रोग का खतरा होता है?","solution":"इंसुलिन की कमी से रक्त शर्करा बढ़ जाती है, जिसे मधुमेह (डायबिटीज़) कहते हैं","answer":"मधुमेह (डायबिटीज़)"}$j$),
  (913,'govt_technical','horm-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"रक्त शर्करा को नियंत्रित करने वाला हार्मोन कौन सा है?","options":["इंसुलिन","थायरॉक्सिन","एड्रेनालिन","टेस्टोस्टेरोन"],"answer":0,"explanation":"इंसुलिन रक्त शर्करा का स्तर कम करता है।"},{"q":"थायरॉक्सिन किस ग्रंथि से निकलता है?","options":["थायरॉइड","अग्न्याशय","अधिवृक्क","पीयूष"],"answer":0,"explanation":"थायरॉक्सिन थायरॉइड ग्रंथि से निकलता है और चयापचय नियंत्रित करता है।"}]}$j$),
  (913,'govt_basic','horm-concept','concept',1,'हार्मोन',$j${"note":"परीक्षा में हार्मोन और एंजाइम का अंतर पूछा जाता है।","text":"हार्मोन शरीर के विभिन्न भागों के लिए संदेश का काम करते हैं। ये अंतःस्रावी ग्रंथियों से सीधे रक्त में जाते हैं। इनकी थोड़ी मात्रा भी असर डालती है।"}$j$),
  (913,'govt_basic','horm-formula','formula',2,'रोग और हार्मोन',$j${"formula":"इंसुलिन की कमी → मधुमेह · थायरॉक्सिन की कमी → घेंघा/गलगंड","explanation":"ये सामान्य रूप से परीक्षा में पूछे जाने वाले संबंध हैं"}$j$),
  (913,'govt_basic','horm-example','example',3,'उदाहरण',$j${"question":"वृद्धि (growth) नियंत्रित करने वाला हार्मोन कौन सा है?","solution":"पीयूष ग्रंथि से निकलने वाला वृद्धि हार्मोन शरीर की वृद्धि नियंत्रित करता है","answer":"वृद्धि हार्मोन (पीयूष ग्रंथि)"}$j$),
  (913,'govt_basic','horm-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"'मास्टर ग्रंथि' किसे कहते हैं?","options":["पीयूष ग्रंथि","थायरॉइड","अधिवृक्क","अग्न्याशय"],"answer":0,"explanation":"पीयूष ग्रंथि अन्य अंतःस्रावी ग्रंथियों को नियंत्रित करती है, इसलिए इसे मास्टर ग्रंथि कहते हैं।"},{"q":"आपात स्थिति में हृदय गति बढ़ाने वाला हार्मोन कौन सा है?","options":["एड्रेनालिन","इंसुलिन","थायरॉक्सिन","टेस्टोस्टेरोन"],"answer":0,"explanation":"एड्रेनालिन आपात स्थिति (लड़ो या भागो) में हृदय गति बढ़ाता है।"}]}$j$),
  (913,null,'horm-diagram','svg',5,'प्रमुख अंतःस्रावी ग्रंथियाँ',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g font-size='11' fill='#0f172a' text-anchor='middle'><rect x='20' y='20' width='70' height='30' fill='#c4b5fd' rx='6'/><text x='55' y='39'>पीयूष</text><rect x='115' y='20' width='70' height='30' fill='#fbcfe8' rx='6'/><text x='150' y='39'>थायरॉइड</text><rect x='210' y='20' width='70' height='30' fill='#fde047' rx='6'/><text x='245' y='39'>अधिवृक्क</text><rect x='115' y='75' width='70' height='30' fill='#86efac' rx='6'/><text x='150' y='94'>अग्न्याशय</text></g></svg>","caption":"प्रमुख अंतःस्रावी ग्रंथियों के स्थान"}$j$),
  (914,'govt_technical','skel-concept','concept',1,'कंकाल और पेशी तंत्र — SSC JE / RRB JE',$j${"note":"परीक्षा में मनुष्य में हड्डियों की संख्या, कंकाल के भाग और पेशियों के प्रकार अक्सर पूछे जाते हैं।","text":"वयस्क मनुष्य में लगभग 206 हड्डियाँ होती हैं। कंकाल अक्षीय (खोपड़ी, कशेरुकदंड, पसलियाँ) और उपांगीय (हाथ-पैर, मेखलाएँ) भागों में बँटा है। पेशियाँ तीन प्रकार की होती हैं: कंकाली (ऐच्छिक), चिकनी (अनैच्छिक, आंतरिक अंगों में) और हृदय पेशी।"}$j$),
  (914,'govt_technical','skel-formula','formula',2,'जोड़ों के प्रकार',$j${"formula":"कब्ज़ा (हिंज) जोड़ — कोहनी व घुटना · बॉल-सॉकेट जोड़ — कंधा व कूल्हा","explanation":"बॉल-सॉकेट जोड़ सभी दिशाओं में गति देते हैं"}$j$),
  (914,'govt_technical','skel-example','example',3,'Numerical (JE style)',$j${"question":"वयस्क मनुष्य के शरीर में लगभग कितनी हड्डियाँ होती हैं?","solution":"वयस्क मनुष्य में लगभग 206 हड्डियाँ होती हैं, जबकि नवजात में अधिक होती हैं","answer":"लगभग 206"}$j$),
  (914,'govt_technical','skel-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"घुटने (knee) का जोड़ किस प्रकार का है?","options":["कब्ज़ा (हिंज) जोड़","बॉल-सॉकेट जोड़","धुरी जोड़","सरकने वाला जोड़"],"answer":0,"explanation":"घुटना कब्ज़ा जोड़ है, जो एक दिशा में गति देता है।"},{"q":"अनैच्छिक चिकनी पेशी कहाँ पाई जाती है?","options":["आंतरिक अंगों में","हाथ-पैर में","हृदय में","चेहरे पर"],"answer":0,"explanation":"चिकनी पेशी आहार नली जैसे आंतरिक अंगों में पाई जाती है और अनैच्छिक होती है।"}]}$j$),
  (914,'govt_basic','skel-concept','concept',1,'कंकाल और मांसपेशियाँ',$j${"note":"परीक्षा में हड्डियों के कार्य और मांसपेशियों की गति पूछी जाती है।","text":"हड्डियाँ शरीर को आकार और सहारा देती हैं, अंगों की रक्षा करती हैं और रक्त कोशिकाएँ बनाती हैं। मांसपेशियाँ हड्डियों से जुड़कर संकुचन से गति कराती हैं।"}$j$),
  (914,'govt_basic','skel-formula','formula',2,'हड्डियों के कार्य',$j${"formula":"सहारा + सुरक्षा + गति + रक्त कोशिका निर्माण","explanation":"लाल अस्थि मज्जा रक्त कोशिकाएँ बनाती है"}$j$),
  (914,'govt_basic','skel-example','example',3,'उदाहरण',$j${"question":"खोपड़ी की हड्डी किस कार्य के लिए होती है?","solution":"खोपड़ी मस्तिष्क की रक्षा करती है","answer":"मस्तिष्क की रक्षा"}$j$),
  (914,'govt_basic','skel-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"शरीर की सबसे लंबी हड्डी कौन सी है?","options":["फीमर (जांघ की हड्डी)","ह्यूमरस","टिबिया","स्टेपीज़"],"answer":0,"explanation":"फीमर शरीर की सबसे लंबी और मजबूत हड्डी है।"},{"q":"मांसपेशियाँ किसके द्वारा गति कराती हैं?","options":["संकुचन","फैलाव","रक्त","तापमान"],"answer":0,"explanation":"मांसपेशियाँ संकुचन करके हड्डियों को खींचती हैं, जिससे गति होती है।"}]}$j$),
  (914,null,'skel-diagram','svg',5,'मानव कंकाल के भाग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='150' cy='25' r='16' fill='#e2e8f0' stroke='#64748b' stroke-width='2'/><line x1='150' y1='41' x2='150' y2='90' stroke='#64748b' stroke-width='4'/><line x1='120' y1='55' x2='180' y2='55' stroke='#64748b' stroke-width='3'/><line x1='150' y1='90' x2='130' y2='115' stroke='#64748b' stroke-width='3'/><line x1='150' y1='90' x2='170' y2='115' stroke='#64748b' stroke-width='3'/><text x='220' y='60' font-size='11' fill='#64748b'>अक्षीय: सिर, रीढ़</text></svg>","caption":"कंकाल का अक्षीय भाग: सिर और कशेरुकदंड"}$j$),
  (915,'govt_technical','repr-concept','concept',1,'जनन — SSC JE / RRB JE',$j${"note":"परीक्षा में अलैंगिक और लैंगिक जनन का अंतर, मानव में निषेचन का स्थान और मासिक चक्र के दिन अक्सर पूछे जाते हैं।","text":"जनन से जीव अपनी संख्या बढ़ाते हैं। अलैंगिक जनन में एक ही जनक से संतान बनती है (जैसे द्विखंडन, मुकुलन, बीजाणु)। लैंगिक जनन में दो जनकों के युग्मकों के संलयन से संतान बनती है। मानव में निषेचन फैलोपियन नलिका में होता है और निषेचित अंडा गर्भाशय में रोपित होता है।"}$j$),
  (915,'govt_technical','repr-formula','formula',2,'जनन के प्रकार',$j${"formula":"अलैंगिक: एक जनक · लैंगिक: दो जनक (युग्मक संलयन)","explanation":"अलैंगिक संतानें आनुवंशिक रूप से जनक के समान होती हैं"}$j$),
  (915,'govt_technical','repr-example','example',3,'Numerical (JE style)',$j${"question":"मनुष्य में निषेचन किस स्थान पर होता है?","solution":"निषेचन फैलोपियन नलिका (oviduct) में होता है","answer":"फैलोपियन नलिका"}$j$),
  (915,'govt_technical','repr-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"अमीबा किस प्रकार के जनन से बढ़ता है?","options":["द्विखंडन (अलैंगिक)","लैंगिक","मुकुलन","बीजाणु"],"answer":0,"explanation":"अमीबा द्विखंडन द्वारा अलैंगिक जनन करता है।"},{"q":"पुरुष युग्मक को क्या कहते हैं?","options":["शुक्राणु","अंडाणु","बीजाणु","मुकुल"],"answer":0,"explanation":"शुक्राणु पुरुष का युग्मक है, जो अंडाणु से मिलकर निषेचन करता है।"}]}$j$),
  (915,'govt_basic','repr-concept','concept',1,'जनन',$j${"note":"परीक्षा में जनन के प्रकार और मानव जनन अंग पूछे जाते हैं।","text":"जनन जीवों की संतति बढ़ाने की क्रिया है। मनुष्य में लैंगिक जनन होता है, जिसमें पुरुष और स्त्री दोनों के युग्मक मिलते हैं।"}$j$),
  (915,'govt_basic','repr-formula','formula',2,'मानव जनन अंग',$j${"formula":"पुरुष: वृषण (शुक्राणु) · स्त्री: अंडाशय (अंडाणु)","explanation":"वृषण में शुक्राणु बनते हैं और अंडाशय में अंडाणु"}$j$),
  (915,'govt_basic','repr-example','example',3,'उदाहरण',$j${"question":"स्त्री में अंडाणु किस अंग में बनते हैं?","solution":"स्त्री में अंडाणु अंडाशय (ovary) में बनते हैं","answer":"अंडाशय"}$j$),
  (915,'govt_basic','repr-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"कौन सा जीव मुकुलन (budding) से जनन करता है?","options":["हाइड्रा","अमीबा","मलेरिया परजीवी","पैरामीशियम"],"answer":0,"explanation":"हाइड्रा मुकुलन द्वारा अलैंगिक जनन करता है।"},{"q":"पुरुष में शुक्राणु किस अंग में बनते हैं?","options":["वृषण","अंडाशय","गर्भाशय","प्रोस्टेट"],"answer":0,"explanation":"वृषण (testis) में शुक्राणु बनते हैं।"}]}$j$),
  (915,null,'repr-diagram','svg',5,'लैंगिक जनन का चरण',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='60' cy='60' r='22' fill='#60a5fa'/><text x='60' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>शुक्राणु</text><circle cx='140' cy='60' r='22' fill='#fbcfe8'/><text x='140' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>अंडाणु</text><line x1='170' y1='60' x2='210' y2='60' stroke='#64748b' stroke-width='3'/><circle cx='240' cy='60' r='22' fill='#86efac'/><text x='240' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>युग्मनज</text></svg>","caption":"शुक्राणु और अंडाणु के संलयन से युग्मनज बनता है"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
